action.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const body = { client: "dashboard", emailAddress: "admin@schule.de", schoolSlug: "eckener-schule" };
  const r = await fetch("http://backend:4000/api/v1/auth/init-email-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  console.log("init-email-login HTTP", r.status, (await r.text()).slice(0,120));
})();
' && sleep 3 && echo "=== relay logs (newest first) ===" && docker logs --tail 40 smtp-sink 2>&1 | tail -40

